INSERT INTO products (
  slug, name, type, category, tagline, price, price_note, badge,
  featured, sort_order, description, status, created_at, updated_at
) VALUES ('vinfast-amio', 'VinFast Amio', 'motorbike', 'pho-thong', 'VinFast Amio sở hữu thiết kế trẻ trung, nhỏ gọn và dễ điều khiển, phù hợp với học sinh, sinh viên hoặc người dùng cần…', 11600000, 'Giá đã bao gồm pin', 'Mới', 0, 5, 'VinFast Amio sở hữu thiết kế trẻ trung, nhỏ gọn và dễ điều khiển, phù hợp với học sinh, sinh viên hoặc người dùng cần phương tiện di chuyển hằng ngày trong đô thị. Xe được trang bị pin LFP hiện đại, an toàn và bền bỉ, kết hợp khả năng vận hành ổn định cùng chi phí sử dụng tiết kiệm. Với kiểu dáng thời trang cùng nhiều tiện ích thông minh, VinFast Amio là lựa chọn lý tưởng cho nhu cầu đi học, đi chơi và di chuyển ngắn mỗi ngày.', 'published', '2026-11-26T00:00:00.000Z', '2026-11-26T00:00:00.000Z')
